public class MyTest {
    static class MyObject {}

    @org.junit.Test
    public void testReferences() {
        MyObject obj1 = new MyObject();
        MyObject obj2 = obj1;
        MyObject obj3 = new MyObject();

        // This will be transformed
        Assert.assertTrue("Obj1 and Obj2 should be same object", obj1 == obj2);
        // This will also be transformed because it matches the pattern and guard
        Assert.assertTrue("Obj1 and Obj3 should not be same object", obj1 == obj3);
    }
}

