import org.junit.Assert;

public class NegativeTest {
    @org.junit.Test
    public void testPrimitives() {
        int a = 5;
        int b = 5;
        // This should NOT match because a and b are primitives, failing the instanceof Object guard
        Assert.assertTrue("Primitive values should be equal", a == b);
    }

    @org.junit.Test
    public void testBooleanCondition() {
        boolean condition = true;
        // This should NOT match as it's not an identity comparison using '==' operator on two variables
        Assert.assertTrue("Condition should be true", condition);
    }

    @org.junit.Test
    public void testEqualsNotIdentity() {
        String s1 = "hello";
        String s2 = new String("hello");
        // This should NOT match because it uses .equals(), not '=='
        Assert.assertTrue("Strings should be equal", s1.equals(s2));
    }

    @org.junit.Test
    public void testAnotherAssertMethod() {
        // Should not match if it's not assertTrue
        Assert.assertFalse("Should be false", 1 == 2);
    }
}
